// This file is the single definition of which outer fields an AuditRecord
// carries for every audit-side treatment of record envelope content: the
// fingerprint's raw canonical encoder and the valid-UTF-8 test that chooses
// between the JSON and raw fingerprint families, the valid-UTF-8 JSON
// envelope itself, and the archive writer and reader. Each of those walks
// the one table below instead of naming org, sequence, category, payloads
// and predecessor fingerprint itself, so the fields and their order mean the
// same thing everywhere. Adding or changing an outer field here reaches
// fingerprinting, the UTF-8 decision, archiving and unarchiving at once; no
// audit path can keep a stale list of its own.
//
// The table order is part of the wire and fingerprint contract: it is the
// historical envelope field order — the organization, the gapless sequence,
// the category, the two payloads and the predecessor fingerprint — and the
// archive mirrors it field for field. Nested policy, policy-change and
// decision content stays governed by its own single field tables
// (policy_fields.go, change_fields.go, decision_fields.go). Record creation
// itself (appendAuditLocked) and chain validation (VerifyAudit) are
// intentionally not driven from this table: they name fields for
// chain-semantic reasons (sequence continuity, category/payload agreement)
// rather than serialization ones.
//
// One outer field deliberately appears in no fingerprint encoding and hence
// in no protected-fields list: AuditRecord.Fingerprint. A record's own
// current fingerprint is the output of the hash, never its own input, so it
// must not protect itself; it is still an outer field and the archive writes
// and reads it separately at the tail of each record.
package darksafe

import (
	"bytes"
	"encoding/json"
	"unicode/utf8"
)

// recordFieldKind says how one outer record field participates in
// fingerprinting and archiving.
type recordFieldKind int

const (
	// recordFieldString is an outer string written from its exact bytes by
	// the raw encoder and as a JSON string by the legacy encoder.
	recordFieldString recordFieldKind = iota
	// recordFieldInt is a non-negative integer (the gapless sequence). It
	// has no UTF-8 representation, so the valid-UTF-8 scan skips it while
	// both encoders write it.
	recordFieldInt
	// recordFieldChangePayload is the policy-change payload. It is
	// fingerprinted with omitempty like the legacy JSON envelope's
	// "change,omitempty" tag and reaches the raw encoder through the single
	// policy-change field table.
	recordFieldChangePayload
	// recordFieldDecisionPayload is the decision payload. It is
	// fingerprinted with omitempty like the legacy JSON envelope's
	// "decision,omitempty" tag and reaches the raw encoder through the
	// single decision field table.
	recordFieldDecisionPayload
)

// recordFieldSpec locates one protected outer AuditRecord field. A field
// appears in recordFields exactly once, and that entry is the only place its
// struct member is named for serialization. The JSON key, raw group marker
// and accessors exist per kind:
//
//   - string fields use getString, carry jsonKey and no group marker;
//   - integer fields use getInt, and emit tagSeq;
//   - payload fields use getChange/getDecision, carry jsonKey, omitempty
//     semantics and, for the raw encoder, the same nesting marker the
//     historical encoding placed there.
//
// The accessor signature deliberately takes *AuditRecord directly (unlike
// the payload tables' narrow receiver), because the envelope is built from
// the public record without any intermediate copy: removing hashEnvelope
// was what made this table the one place these fields are listed.
type recordFieldSpec struct {
	kind recordFieldKind

	// jsonKey is the legacy envelope's member name ("org", "seq", "kind",
	// "change", "decision", "prev"). Integer fields use "seq"; it stays set
	// for uniformity even though json.Marshal over the table emits it via
	// mapstructure-like assembly here rather than via struct tags.
	jsonKey string

	// rawTag, when non-zero, is emitted immediately before this field's
	// value by the raw canonical encoder, reproducing the historical
	// encoding's nesting markers (the payload group tags, the sequence
	// tag). String fields carry tagString unconditionally and ints carry
	// tagSeq; payload fields carry tagChange/tagDecisionRecord.
	rawTag fingerprintTag

	getString   func(*AuditRecord) string
	getInt      func(*AuditRecord) int
	getChange   func(*AuditRecord) *PolicyChange
	getDecision func(*AuditRecord) *DecisionRecord
}

// recordFields lists every outer field protected by a record fingerprint in
// historical envelope order, which both fingerprint families and the archive
// reproduce exactly: organization, sequence, category, policy-change
// payload, decision payload, predecessor fingerprint. AuditRecord.Fingerprint
// is deliberately absent: the current fingerprint is never its own hash
// input.
var recordFields = [...]recordFieldSpec{
	{
		kind:      recordFieldString,
		jsonKey:   "org",
		rawTag:    tagString,
		getString: func(r *AuditRecord) string { return r.Org },
	},
	{
		kind:    recordFieldInt,
		jsonKey: "seq",
		rawTag:  tagSeq,
		getInt:  func(r *AuditRecord) int { return r.Seq },
	},
	{
		kind:      recordFieldString,
		jsonKey:   "kind",
		rawTag:    tagString,
		getString: func(r *AuditRecord) string { return r.Kind },
	},
	{
		kind:      recordFieldChangePayload,
		jsonKey:   "change",
		rawTag:    tagChange,
		getChange: func(r *AuditRecord) *PolicyChange { return r.Change },
	},
	{
		kind:        recordFieldDecisionPayload,
		jsonKey:     "decision",
		rawTag:      tagDecisionRecord,
		getDecision: func(r *AuditRecord) *DecisionRecord { return r.Decision },
	},
	{
		kind:      recordFieldString,
		kind2:     0,
		jsonKey:   "prev",
		rawTag:    tagString,
		getString: func(r *AuditRecord) string { return r.PrevFingerprint },
	},
}

// recordJSONEnvelope is assembled field by field from recordFields when
// reproducing the legacy valid-UTF-8 fingerprint. It must stay structurally
// identical to the former hashEnvelope: JSON field order is declaration
// order, matching org, seq, kind, change omitempty, decision omitempty, prev.
type recordJSONEnvelope struct {
	Org             string          `json:"org"`
	Seq             int             `json:"seq"`
	Kind            string          `json:"kind"`
	Change          *PolicyChange   `json:"change,omitempty"`
	Decision        *DecisionRecord `json:"decision,omitempty"`
	PrevFingerprint string          `json:"prev"`
}

// marshalRecordEnvelopeJSON produces exactly the bytes the old
// json.Marshal(hashEnvelope{...}) produced for r, but it populates the
// envelope by walking recordFields rather than naming the members a second
// time. Because the one table lists each field exactly once in the same
// order and recordJSONEnvelope keeps the identical declaration and tags,
// output is byte-identical.
func marshalRecordEnvelopeJSON(r *AuditRecord) ([]byte, error) {
	env := recordJSONEnvelope{}
	for i := range recordFields {
		f := &recordFields[i]
		switch f.kind {
		case recordFieldString:
			// Three string fields occupy fixed envelope members; identify
			// them through the table's JSON key rather than by index, so a
			// reordering in the table cannot silently cross the wires.
			switch f.jsonKey {
			case "org":
				env.Org = f.getString(r)
			case "kind":
				env.Kind = f.getString(r)
			case "prev":
				env.PrevFingerprint = f.getString(r)
			}
		case recordFieldInt:
			env.Seq = f.getInt(r)
		case recordFieldChangePayload:
			env.Change = f.getChange(r)
		case recordFieldDecisionPayload:
			env.Decision = f.getDecision(r)
		}
	}
	return json.Marshal(&env)
}

// writeEnvelopeRaw writes r's protected outer fields to the canonical
// raw-byte encoder by walking recordFields, then writes PrevFingerprint
// last — all in the table's (historical) order. Payload fields always emit
// their group marker (e.change/e.decisionRecord themselves distinguish nil
// from present), reproducing tagEnvelope + org + seq + kind + change +
// decision + prev exactly.
//
// It must NOT write r.Fingerprint.
func writeEnvelopeRaw(e *fingerprintEncoder, r *AuditRecord) {
	for i := range recordFields {
		f := &recordFields[i]
		switch f.kind {
		case recordFieldString:
			e.rawString(f.getString(r))
		case recordFieldInt:
			e.int64Tag(f.rawTag, int64(f.getInt(r)))
		case recordFieldChangePayload:
			e.change(f.getChange(r))
		case recordFieldDecisionPayload:
			e.decisionRecord(f.getDecision(r))
		}
	}
}

// envelopeUsesRawBytes reports whether any string protected by the
// fingerprint carries bytes that are not valid UTF-8. Such envelopes are
// hashed through writeEnvelopeRaw instead of encoding/json, because JSON
// string encoding replaces invalid bytes with U+FFFD and would let two
// different raw contents share a fingerprint. It ranges the single outer
// field table, so its idea of which outer content the fingerprint protects
// can never diverge from the fields the encoders write; which strings nested
// payloads carry is decided by the single change and decision field tables.
func envelopeUsesRawBytes(r *AuditRecord) bool {
	for i := range recordFields {
		f := &recordFields[i]
		switch f.kind {
		case recordFieldString:
			if !utf8.ValidString(f.getString(r)) {
				return true
			}
		case recordFieldInt:
			// Integer content cannot carry a raw byte.
		case recordFieldChangePayload:
			if c := f.getChange(r); c != nil {
				if changeHasNonUTF8(c) {
					return true
				}
			}
		case recordFieldDecisionPayload:
			if d := f.getDecision(r); d != nil {
				if decisionRecordHasNonUTF8(d) {
					return true
				}
			}
		}
	}
	return false
}

// encodeCanonical returns the raw bytes fingerprinted for a record whose
// strings include invalid UTF-8. Every string the record carries reaches the
// output byte-for-byte, at whatever nesting depth or list position it
// occupies. The prefix separates this encoding space from JSON
// fingerprints.
func encodeCanonical(r *AuditRecord) []byte {
	e := &fingerprintEncoder{buf: []byte(rawEnvelopePrefix)}
	e.tag(tagEnvelope)
	writeEnvelopeRaw(e, r)
	return e.buf
}

// marshalEnvelopeForFingerprint dispatches between the two fingerprint
// families exactly as the historical computeFingerprint did: raw content
// uses the length-prefixed canonical bytes, everything else keeps the JSON
// envelope. Both families enumerate their protected fields exclusively from
// recordFields.
func marshalEnvelopeForFingerprint(r *AuditRecord) ([]byte, string) {
	if envelopeUsesRawBytes(r) {
		return encodeCanonical(r), "raw"
	}
	b, err := marshalRecordEnvelopeJSON(r)
	if err != nil {
		// All envelope fields are plain, JSON-encodable values; a failure
		// here indicates a programming error, not user input.
		panic(err)
	}
	return b, "json"
}

// bytesBuffer satisfies the archive-oriented helpers below without
// importing bytes into audit.go; the archive path owns its framing.
var _ = bytes.MinRead

