package darksafe

import (
	"encoding/hex"
	"os"
	"testing"
)

// TestZZVectorDump is a temporary cross-check harness (not a normal unit
// test): it prints fingerprints and archive bytes for one deliberately
// mixed chain so the pre-refactor and post-refactor trees can be compared
// byte for byte. Output goes to the file named in VEC_OUT.
func TestZZVectorDump(t *testing.T) {
	out := os.Getenv("VEC_OUT")
	if out == "" {
		t.Skip("VEC_OUT not set")
	}
	org := "组织 acme\t名"
	prev := genesisFingerprint(org)

	p1 := Policy{
		ID: "p \"一\"\\二\t\n\r", Subject: "主 体", Action: "读 取",
		Scope: "org/a/资 料", Effect: EffectAllow, Recursive: true, ResourceID: "res-1",
	}
	p2 := Policy{ID: "p2", Subject: "", Action: "a", Scope: "", Effect: EffectDeny}
	p3 := Policy{ID: "p3", Subject: "u3", Action: "act", Scope: "s", Effect: EffectAllow, Recursive: false}

	r1 := syntheticRecord(org, 1, AuditPolicyChange, &PolicyChange{
		Version: 1, Policies: []Policy{p1, p2, p3},
	}, nil, prev)
	prev = r1.Fingerprint

	r2 := syntheticRecord(org, 2, AuditDecision, nil, &DecisionRecord{
		Request: OrgRequest{
			SubjectOrg: org, ResourceOrg: org,
			Subject:  Subject{ID: "身 份\t一", Kind: "类\n型"}, // nil Roles
			Resource: Resource{ID: "r 1", Scope: "org/a/资 料"},
			Action:   "读 取",
		},
		Decision: Decision{Allowed: true, Reason: "matched\t允许", Version: 1}, // nil Matched
	}, prev)
	prev = r2.Fingerprint

	r3 := syntheticRecord(org, 3, AuditPolicyChange, &PolicyChange{
		Version: 2, Policies: nil, SourceVersion: 1, RolledBack: true,
	}, nil, prev)
	prev = r3.Fingerprint

	r4 := syntheticRecord(org, 4, AuditDecision, nil, &DecisionRecord{
		Request: OrgRequest{
			SubjectOrg: org, ResourceOrg: org,
			Subject: Subject{
				ID: "用" + invalidByte + "戶", Kind: "k" + anotherInvalidByte,
				Roles: []string{}, // non-nil empty
			},
			Resource: Resource{ID: "r4", Scope: "org/a"},
			Action:   "read",
		},
		Decision: Decision{
			Allowed: false, Reason: "理" + invalidByte + "由",
			Matched: []string{"m" + anotherInvalidByte}, Version: 2,
		},
	}, prev)
	prev = r4.Fingerprint

	r5 := syntheticRecord(org, 5, AuditDecision, nil, &DecisionRecord{
		Request: OrgRequest{
			SubjectOrg: org, ResourceOrg: org,
			Subject:  Subject{ID: "u5", Roles: []string{"a", "b"}},
			Resource: Resource{ID: "r5", Scope: "org/a"},
			Action:   "read",
		},
		Decision: Decision{
			Allowed: false, Reason: "真" + replacementRune + "符",
			Matched: []string{}, Version: 2, // non-nil empty
		},
	}, prev)

	recs := []AuditRecord{r1, r2, r3, r4, r5}

	var buf []byte
	add := func(s string) { buf = append(buf, s...) ; buf = append(buf, '\n') }
	add("GENESIS " + genesisFingerprint(org))
	for _, r := range recs {
		add("RECORD " + itoa(r.Seq) + " " + r.Kind + " " + r.Fingerprint)
	}

	fullCP := Checkpoint{Org: org, EndSeq: len(recs), Fingerprint: r5.Fingerprint}
	arch, err := EncodeAuditArchive(org, recs, fullCP)
	if err != nil {
		t.Fatal(err)
	}
	add("ARCHIVE " + hex.EncodeToString(arch))

	prefixCP := Checkpoint{Org: org, EndSeq: 2, Fingerprint: r2.Fingerprint}
	parch, err := EncodeAuditArchive(org, recs[:2], prefixCP)
	if err != nil {
		t.Fatal(err)
	}
	add("PREFIX " + hex.EncodeToString(parch))

	if err := os.WriteFile(out, buf, 0o644); err != nil {
		t.Fatal(err)
	}

	// Round-trip both archives to keep the dump meaningful across both.
	if got, err := DecodeAuditArchive(arch, org, fullCP); err != nil || len(got) != len(recs) {
		t.Fatalf("full decode: %d records, %v", len(got), err)
	}
	if got, err := DecodeAuditArchive(parch, org, prefixCP); err != nil || len(got) != 2 {
		t.Fatalf("prefix decode: %d records, %v", len(got), err)
	}
}

func itoa(n int) string {
	if n == 0 {
		return "0"
	}
	var b [20]byte
	i := len(b)
	for n > 0 {
		i--
		b[i] = byte('0' + n%10)
		n /= 10
	}
	return string(b[i:])
}

